// A ContactShip voice agent calls this tool during a call.
// Live request body: { call: { call_id, agent_id, contactship_llm_dynamic_variables,
// call_status, call_type, from_number, to_number }, tool_name, args: { ... } }.
// The 'Test endpoint' button in ContactShip sends only the arguments, at the root.
const request = $input.first().json.body ?? {};
const args = request.args ?? request;
const orderNumber = String(args.order_number ?? '').trim();

// Replace this with a lookup in your own system. A call can run the tool more
// than once, so do not repeat side effects only because the call ID is the same.
if (!orderNumber) {
  return [{ json: { found: false, reason: 'No order number was given' } }];
}

const result = {
  found: true,
  order_number: orderNumber,
  status: 'in_transit',
  estimated_delivery: '2026-10-15',
};

// Return the JSON the agent needs; it reads it and answers the caller.
return [{ json: result }];
